insert into storage.buckets (id,name,public,file_size_limit,allowed_mime_types) values ('meta-ad-media','meta-ad-media',false,209715200,array['image/jpeg','image/png','image/webp','video/mp4','video/quicktime']) on conflict (id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create table if not exists public.meta_ad_workspace_settings (workspace_id uuid primary key references public.workspaces(id) on delete cascade,ad_account_id text not null check(ad_account_id ~ '^act_[0-9]+$'),updated_by uuid references auth.users(id) on delete set null,updated_at timestamptz not null default now());
create table if not exists public.meta_ad_creative_drafts (id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,file_name text not null check(char_length(file_name) between 1 and 240),media_type text not null check(media_type in ('image','video')),storage_path text not null unique,meta_asset_id text,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
alter table public.meta_ad_workspace_settings enable row level security; alter table public.meta_ad_creative_drafts enable row level security; create index if not exists meta_ad_creative_drafts_workspace_created_idx on public.meta_ad_creative_drafts(workspace_id,created_at desc);
